def three_sum(nums):
    n = len(nums)
    found = set()
    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                if nums[i] + nums[j] + nums[k] == 0:
                    trip = tuple(sorted([nums[i], nums[j], nums[k]]))
                    found.add(trip)
    return [list(t) for t in sorted(found)]

